function largestBalancedBits(s: string): string {
  const n = s.length;
  const seen = new Set<string>([s]);
  const queue = [s];
  let best = s;
  for (let head = 0; head < queue.length; head++) {
    const t = queue[head];
    if (t > best) best = t;
    // pre[i] = (1s − 0s) in t[0..i); a substring t[i..j) is balanced if pre[i] == pre[j] and never dips below pre[i]
    const pre = [0];
    for (const ch of t) pre.push(pre[pre.length - 1] + (ch === "1" ? 1 : -1));
    const balanced = (i: number, j: number) => {
      if (pre[i] !== pre[j]) return false;
      for (let k = i; k <= j; k++) if (pre[k] < pre[i]) return false;
      return true;
    };
    for (let i = 0; i < n; i++)
      for (let j = i + 2; j < n; j += 2) {
        if (!balanced(i, j)) continue;
        for (let k = j + 2; k <= n; k += 2) {
          if (!balanced(j, k)) continue;
          const u = t.slice(0, i) + t.slice(j, k) + t.slice(i, j) + t.slice(k);
          if (!seen.has(u)) { seen.add(u); queue.push(u); }
        }
      }
  }
  return best;
}

