function largestBalancedBits(s: string): string {
  const blocks: string[] = [];
  let bal = 0, start = 0;
  for (let i = 0; i < s.length; i++) {
    bal += s[i] === "1" ? 1 : -1;
    if (bal === 0) {
      // s[start..i] is one block "1 X 0": maximise X, then wrap it again
      blocks.push("1" + largestBalancedBits(s.slice(start + 1, i)) + "0");
      start = i + 1;
    }
  }
  blocks.sort((a, b) => (a < b ? 1 : a > b ? -1 : 0));
  return blocks.join("");
}

